def merge_config(base, patch):
    """
    Merge nested configuration dictionaries recursively.

    Args:
        base (dict): Base configuration dictionary.
        patch (dict): Patch configuration dictionary.

    Returns:
        dict: Merged configuration dictionary.
    """
    if isinstance(base, dict) and isinstance(patch, dict):
        # Merge dictionaries recursively
        return {
            **base,
            **patch,
            **{**base, **patch}
        }
    elif isinstance(base, dict) and isinstance(patch, list):
        # Merge list with patch
        return list(base) + patch
    elif isinstance(base, list) and isinstance(patch, dict):
        # Merge list with patch
        return list(base)
    else:
        # If neither is a dict or list, return base
        return base
